package com.bibliotech.book.entity; import jakarta.persistence.*; @Entity public class Book{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String title; private String author; @Column(unique=true) private String isbn; private String category; private int totalCopies; private int availableCopies; public Long getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getAuthor(){return author;} public void setAuthor(String v){author=v;} public String getIsbn(){return isbn;} public void setIsbn(String v){isbn=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public int getTotalCopies(){return totalCopies;} public void setTotalCopies(int v){totalCopies=v;} public int getAvailableCopies(){return availableCopies;} public void setAvailableCopies(int v){availableCopies=v;}}
